using System.Text.Json;
using VisionPlugins.MapCalibration;
float[] a=[2,0,10,0,3,-5,0,0,1],b=[4,0,-2,0,6,7,0,0,1],z=new float[9],identity=[1,0,0,0,1,0,0,0,1],mapped=[.5f,0,3,0,.5f,-2,0,0,1];int count=0;
foreach(var line in File.ReadLines("analysis/map-calibration/native/results.jsonl")){using var d=JsonDocument.Parse(line);var r=d.RootElement;int c=r.GetProperty("case").GetInt32();if(c<2)continue;float[] source=c switch{2 or 3=>a,4 or 5=>identity,6=>z,7=>[2,0,10,0,3,-5,.01f,-.02f,1],_=>r.GetProperty("source").EnumerateArray().Select(x=>x.GetSingle()).ToArray()};float[] target=c switch{2=>a,4=>mapped,5=>z,_=>c>=8?r.GetProperty("target").EnumerateArray().Select(x=>x.GetSingle()).ToArray():b};var result=MapCalibrationSolver.SolveFiles(source,target);if(r.TryGetProperty("exception",out var error)){if(result.ErrorCode!=error.GetUInt32())throw new Exception("Exception mismatch "+c);count++;continue;}var expected=r.GetProperty("matrix").EnumerateArray().Select(x=>x.GetSingle()).ToArray();for(int i=0;i<9;i++){if(BitConverter.SingleToInt32Bits(result.Matrix[i])!=BitConverter.SingleToInt32Bits(expected[i]))throw new Exception($"Matrix bit mismatch {c}/{i}: {result.Matrix[i]} vs {expected[i]}");count++;}var ratio=r.GetProperty("ratio").EnumerateArray().Select(x=>x.GetSingle()).ToArray();if(result.XRatio!=ratio[0]||result.YRatio!=ratio[1])throw new Exception("Ratio mismatch "+c);count+=2;}Console.WriteLine($"PASS {count}: original SDK file matrix/ratio bit comparisons and singular target error");


File.WriteAllText("analysis/map-calibration/file-solver-checks.json",JsonSerializer.Serialize(new{checks=count,passed=true,comparison="float-bit equality for matrix and ratios plus original target-singular errors",generatedUtc=DateTime.UtcNow}));
